// =========================================================================
// 04_MYTHIC_VICTINI_VICTORY_STAR - Modern HTML5 Canvas 2D Implementation
// 100% Anatomical Likeness & High-End 3D Pop Mart Vinyl Aesthetic
// Organic Micro-Physics: 5% Squash & Stretch, Flap Lag 0.45 rad, Ear Flames
// =========================================================================
function drawVictiniVictoryStar(ctx, cx, cy, scale, t) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  // 1. Organic Micro-Physics Kinematics
  const breathFreq = 2.4; // Tần số nhịp thở/nhún nhảy năng lượng tích cực
  const breathPhase = t * breathFreq;
  const breathSin = Math.sin(breathPhase);

  // Squash & Stretch 5% bảo toàn thể tích
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const bounceY = -Math.abs(breathSin) * 3.5; // Độ nảy nhún đàn hồi
  const by = bounceY; // base Y offset for body

  // Đôi cánh nhỏ sau lưng vỗ nhịp trễ pha Delta Phi = 0.45 rad
  const wLag = breathPhase - 0.45;
  const wFlapL = Math.sin(wLag) * 4.5;
  const wFlapR = Math.sin(wLag + 0.15) * 4.5;

  // Lửa chóp tai bập bùng tần số cao
  const flameF1 = Math.sin(t * 14.0) * 3.0 + Math.cos(t * 22.0) * 1.8;
  const flameF2 = Math.cos(t * 16.0) * 2.8 + Math.sin(t * 24.0) * 1.6;

  // Nhịp chớp mắt 3.5s (interval 3500ms, duration 140ms)
  const blinkCycle = (t * 1000) % 3500;
  const blink = blinkCycle < 140;

  // 2. LAYER 0: BÓNG TIẾP XÚC MẶT ĐẤT CO GIÃN (Dynamic Ground Contact Shadow)
  ctx.save();
  const shadowScale = (1.0 - bounceY * 0.04);
  const shadowGrad = ctx.createRadialGradient(-8, 86, 4, -8, 86, 40 * sX * shadowScale);
  shadowGrad.addColorStop(0, "rgba(18, 22, 30, 0.70)");
  shadowGrad.addColorStop(0.55, "rgba(22, 26, 36, 0.35)");
  shadowGrad.addColorStop(1, "rgba(22, 26, 36, 0.0)");
  ctx.fillStyle = shadowGrad;
  ctx.beginPath();
  ctx.ellipse(-8, 86, 40 * sX * shadowScale, 9.5 * sX * shadowScale, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  // 3. LAYER 1: CÁNH LÔNG VŨ SAU LƯNG (Feathered Wing Tails with Phase Lag)
  // Cánh trái (viewer's left)
  ctx.save();
  ctx.translate(-26, by + 48);
  ctx.rotate((-16 + wFlapL * 1.2) * Math.PI / 180);
  for (let i = 0; i < 3; i++) {
    const angle = -0.32 + i * 0.28;
    const len = 22 + i * 3.0;
    ctx.save();
    ctx.rotate(angle);
    const grad = ctx.createLinearGradient(0, 0, -len, 0);
    grad.addColorStop(0, "#FCE39E");
    grad.addColorStop(0.7, "#F6DC92");
    grad.addColorStop(1, "#DAB052");
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.ellipse(-len * 0.5, 0, len * 0.55, 4.5, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = "#C99A3A";
    ctx.lineWidth = 0.8;
    ctx.stroke();
    ctx.restore();
  }
  ctx.restore();

  // Cánh phải (viewer's right)
  ctx.save();
  ctx.translate(28, by + 56);
  ctx.rotate((18 + wFlapR * 1.2) * Math.PI / 180);
  for (let i = 0; i < 3; i++) {
    const angle = -0.28 + i * 0.28;
    const len = 24 + i * 3.0;
    ctx.save();
    ctx.rotate(angle);
    const grad = ctx.createLinearGradient(0, 0, len, 0);
    grad.addColorStop(0, "#FCE39E");
    grad.addColorStop(0.7, "#F6DC92");
    grad.addColorStop(1, "#DAB052");
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.ellipse(len * 0.5, 0, len * 0.55, 4.5, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = "#C99A3A";
    ctx.lineWidth = 0.8;
    ctx.stroke();
    ctx.restore();
  }
  ctx.restore();

  // 4. LAYER 2: ĐÔI TAI CHỮ V KHỔNG LỒ (Giant Iconic V-Ears - Exact Wedges)
  // 4.1 TAI PHẢI (Viewer's Right Ear - Huge Diagonal V-Wing)
  ctx.save();
  ctx.translate(0, by);

  // Khối thân tai kem phía dưới kết nối với đầu/cổ
  ctx.beginPath();
  ctx.moveTo(-4, -18);
  ctx.lineTo(112, -52); // Đỉnh nhọn tai phải
  ctx.lineTo(34, -2);   // Gốc dưới tai nối đầu
  ctx.closePath();
  ctx.fillStyle = "#FCE39E";
  ctx.fill();
  ctx.strokeStyle = "#E2BA63";
  ctx.lineWidth = 1.0;
  ctx.stroke();

  // LÒNG TAI ĐEN NHUNG TAM GIÁC RỘNG (Deep Velvet Black Inner Cavity)
  ctx.beginPath();
  ctx.moveTo(10, -14);
  ctx.lineTo(88, -43);
  ctx.lineTo(30, 4);
  ctx.closePath();
  const innerR = ctx.createLinearGradient(10, -14, 88, -43);
  innerR.addColorStop(0, "#0A0A0B");
  innerR.addColorStop(0.5, "#1A1819");
  innerR.addColorStop(1, "#2C282A");
  ctx.fillStyle = innerR;
  ctx.fill();

  // MẶT TRÊN TAI MÀU CAM RỰC LỬA (Flame Orange Upper Ridge Wedge)
  ctx.beginPath();
  ctx.moveTo(-4, -18);
  ctx.lineTo(112, -52);
  ctx.lineTo(82, -40);
  ctx.lineTo(6, -11);
  ctx.closePath();
  const earGradR = ctx.createLinearGradient(-4, -18, 112, -52);
  earGradR.addColorStop(0, "#D63F10");
  earGradR.addColorStop(0.4, "#F35824");
  earGradR.addColorStop(1, "#FF844B");
  ctx.fillStyle = earGradR;
  ctx.fill();
  ctx.strokeStyle = "#B83208";
  ctx.lineWidth = 1.0;
  ctx.stroke();

  // Sống tai bắt sáng trên
  ctx.strokeStyle = "rgba(255, 235, 200, 0.8)";
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(-4, -18);
  ctx.lineTo(110, -51);
  ctx.stroke();
  ctx.restore();

  // 4.2 TAI TRÁI (Viewer's Left Ear - Massive Upward Triangular Spire)
  ctx.save();
  ctx.translate(0, by);

  // Thân tai trái hình nêm tam giác khổng lồ vươn thẳng đứng
  ctx.beginPath();
  ctx.moveTo(-32, -4);  // Chân tai trái ngoài cùng
  ctx.lineTo(-6, -92);  // Đỉnh tai nhọn vút cao
  ctx.lineTo(-4, -18);  // Khe chữ V giữa trán
  ctx.closePath();

  const earGradL = ctx.createLinearGradient(-6, -92, -28, -4);
  earGradL.addColorStop(0, "#FF844B");
  earGradL.addColorStop(0.35, "#F35824");
  earGradL.addColorStop(1, "#D63F10");
  ctx.fillStyle = earGradL;
  ctx.fill();
  ctx.strokeStyle = "#B83208";
  ctx.lineWidth = 1.2;
  ctx.stroke();

  // Đổ bóng 3D mặt sau vát của tai trái
  ctx.beginPath();
  ctx.moveTo(-6, -92);
  ctx.lineTo(-4, -18);
  ctx.lineTo(-12, -14);
  ctx.closePath();
  ctx.fillStyle = "rgba(180, 50, 10, 0.35)";
  ctx.fill();

  // Sống tai vát sáng 3D ngoài cùng
  ctx.strokeStyle = "rgba(255, 235, 200, 0.85)";
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.moveTo(-31, -4);
  ctx.lineTo(-7, -90);
  ctx.stroke();
  ctx.restore();

  // 4.3 HÀO QUANG LỬA CHIẾN THẮNG TRÊN CHÓP TAI (Victory Flame Wisps)
